{
  "css": "#booking-layout {
  border-top: 1px solid #ededf0;
  padding: 20px 0;
}

.booking-host-title {
  margin: 0 0 4px 0;
  font-size: 16px;
  font-weight: 700;
  color: #202024;
  line-height: 1.4;
}

.booking-host-subtitle {
  margin: 0;
  font-size: 14px;
  color: #60606a;
  line-height: 1.4;
}

#booking-actions {
  margin-top: 20px;
}

.booking-icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 48px;
  height: 48px;
  padding: 0;
  border: none;
  background: transparent;
  cursor: pointer;
  color: #202024;
  transition: color 0.15s ease, background-color 0.15s ease;
  border-radius: 6px;
}

.booking-icon-btn img {
  width: 24px;
  height: 24px;
  object-fit: contain;
  pointer-events: none;
}

.booking-icon-btn:hover {
  background-color: #f7f7f8;
  color: #5146d7;
}

.booking-icon-btn[aria-pressed="true"] {
  color: #5146d7;
}

.booking-icon-btn[aria-pressed="true"]:hover {
  background-color: #f0efff;
}

.booking-primary-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 52px;
  height: auto;
  padding: 12px 16px;
  border: none;
  border-radius: 6px;
  background-color: #5146d7;
  color: #ffffff;
  font-size: 16px;
  font-weight: 700;
  line-height: 1.5;
  white-space: normal;
  text-align: center;
  cursor: pointer;
  transition: background-color 0.15s ease, transform 0.1s ease;
}

.booking-primary-btn:hover {
  background-color: #4338c2;
}

.booking-primary-btn:active {
  background-color: #3b31a6;
  transform: scale(0.98);
}

#booking-layout .booking-note {
  margin-top: 12px;
  font-size: 14px;
  color: #60606a;
  line-height: 1.6;
}"
}
